1	use comemo::{Track, Tracked, TrackedMut};
2	use typst_library::diag::SourceResult;
3	use typst_library::engine::{Engine, Route, Sink, Traced};
4	use typst_library::foundations::{
5	    Content, NativeElement, Resolve, Smart, StyleChain, Styles,
6	};
7	use typst_library::introspection::{
8	    Counter, CounterDisplayElem, CounterKey, Introspector, Locator, LocatorLink,
9	};
10	use typst_library::layout::{
11	    Abs, AlignElem, Alignment, Axes, Binding, ColumnsElem, Dir, Frame, HAlignment,
12	    Length, OuterVAlignment, PageElem, Paper, Region, Regions, Rel, Sides, Size,
13	    VAlignment,
14	};
15	use typst_library::model::Numbering;
16	use typst_library::pdf::ArtifactKind;
17	use typst_library::routines::Pair;
18	use typst_library::text::{LocalName, TextElem};
19	use typst_library::visualize::Paint;
20	use typst_library::{Library, World};
21	use typst_utils::{LazyHash, Numeric, Protected};
22	
23	use crate::flow::{ColumnOptions, FlowMode, layout_flow};
24	
25	/// A mostly finished layout for one page. Needs only knowledge of its exact
26	/// page number to be finalized into a `Page`. (Because the margins can depend
27	/// on the page number.)
28	#[derive(Clone)]
29	pub struct LayoutedPage {
30	    pub inner: Frame,
31	    pub margin: Sides<Abs>,
32	    pub margin_two_sided: bool,
33	    pub bleed: Sides<Abs>,
34	    pub bleed_two_sided: bool,
35	    pub binding: Binding,
36	    pub header: Option<Frame>,
37	    pub footer: Option<Frame>,
38	    pub background: Option<Frame>,
39	    pub foreground: Option<Frame>,
40	    pub fill: Smart<Option<Paint>>,
41	    pub numbering: Option<Numbering>,
42	    pub supplement: Content,
43	}
44	
45	/// Layout a single page suitable  for parity adjustment.
46	pub fn layout_blank_page(
47	    engine: &mut Engine,
48	    locator: Locator,
49	    initial: StyleChain,
50	) -> SourceResult<LayoutedPage> {
51	    let layouted = layout_page_run(engine, &[], locator, initial)?;
52	    Ok(layouted.into_iter().next().unwrap())
53	}
54	
55	/// Layout a page run with uniform properties.
56	#[typst_macros::time(name = "page run")]
57	pub fn layout_page_run(
58	    engine: &mut Engine,
59	    children: &[Pair],
60	    locator: Locator,
61	    initial: StyleChain,
62	) -> SourceResult<Vec<LayoutedPage>> {
63	    layout_page_run_impl(
64	        engine.world,
65	        engine.library,
66	        engine.introspector.into_raw(),
67	        engine.traced,
68	        TrackedMut::reborrow_mut(&mut engine.sink),
69	        engine.route.track(),
70	        children,
71	        locator.track(),
72	        initial,
73	    )
74	}
75	
76	/// The internal implementation of `layout_page_run`.
77	#[comemo::memoize]
78	#[expect(clippy::too_many_arguments)]
79	fn layout_page_run_impl(
80	    world: Tracked<dyn World + '_>,
81	    library: &LazyHash<Library>,
82	    introspector: Tracked<dyn Introspector + '_>,
83	    traced: Tracked<Traced>,
84	    sink: TrackedMut<Sink>,
85	    route: Tracked<Route>,
86	    children: &[Pair],
87	    locator: Tracked<Locator>,
88	    initial: StyleChain,
89	) -> SourceResult<Vec<LayoutedPage>> {
90	    let introspector = Protected::from_raw(introspector);
91	    let link = LocatorLink::new(locator);
92	    let mut locator = Locator::link(&link).split();
93	    let mut engine = Engine {
94	        library,
95	        world,
96	        introspector,
97	        traced,
98	        sink,
99	        route: Route::extend(route),
100	    };
101	
102	    // Determine the page-wide styles.
103	    let styles = Styles::root(children, initial);
104	    let styles = StyleChain::new(&styles);
105	
106	    // When one of the lengths is infinite the page fits its content along
107	    // that axis.
108	    let width = styles.resolve(PageElem::width).unwrap_or(Abs::inf());
109	    let height = styles.resolve(PageElem::height).unwrap_or(Abs::inf());
110	    let mut size = Size::new(width, height);
111	    if styles.get(PageElem::flipped) {
112	        std::mem::swap(&mut size.x, &mut size.y);
113	    }
114	
115	    let mut min = width.min(height);
116	    if !min.is_finite() {
117	        min = Paper::A4.width();
118	    }
119	
120	    // Determine the margins.
121	    let default = Rel::<Length>::from((2.5 / 21.0) * min);
122	    let margin = styles.get(PageElem::margin).unwrap_or_default();
123	    let margin_two_sided = margin.two_sided.unwrap_or(false);
124	    let margin = margin
125	        .sides
126	        .map(|side| side.and_then(Smart::custom).unwrap_or(default))
127	        .resolve(styles)
128	        .relative_to(size);
129	
130	    let bleed = styles.get(PageElem::bleed);
131	    let bleed_two_sided = bleed.two_sided.unwrap_or(false);
132	    let bleed = bleed
133	        .sides
134	        .map(|side| side.unwrap_or(Rel::zero()))
135	        .resolve(styles)
136	        .relative_to(size);
137	
138	    let fill = styles.get_cloned(PageElem::fill);
139	    let foreground = styles.get_ref(PageElem::foreground);
140	    let background = styles.get_ref(PageElem::background);
141	    let header_ascent = styles.resolve(PageElem::header_ascent).relative_to(margin.top);
142	    let footer_descent =
143	        styles.resolve(PageElem::footer_descent).relative_to(margin.bottom);
144	    let numbering = styles.get_ref(PageElem::numbering);
145	    let supplement = match styles.get_cloned(PageElem::supplement) {
146	        Smart::Auto => TextElem::packed(PageElem::local_name_in(styles)),
147	        Smart::Custom(content) => content.unwrap_or_default(),
148	    };
149	    let number_align = styles.get(PageElem::number_align);
150	    let binding = styles.get(PageElem::binding).unwrap_or_else(|| {
151	        match styles.resolve(TextElem::dir) {
152	            Dir::LTR => Binding::Left,
153	            _ => Binding::Right,
154	        }
155	    });
156	
157	    // Construct the numbering (for header or footer).
158	    let numbering_marginal = numbering.as_ref().map(|numbering| {
159	        let both = match numbering {
160	            Numbering::Pattern(pattern) => pattern.pieces() >= 2,
161	            Numbering::Func(_) => true,
162	        };
163	
164	        let mut counter = CounterDisplayElem::new(
165	            Counter::new(CounterKey::Page),
166	            Smart::Custom(numbering.clone()),
167	            both,
168	        )
169	        .pack();
170	
171	        // We interpret the Y alignment as selecting header or footer
172	        // and then ignore it for aligning the actual number.
173	        if let Some(x) = number_align.x() {
174	            counter = counter.aligned(x.into());
175	        }
176	
177	        counter
178	    });
179	
180	    let header = styles.get_ref(PageElem::header);
181	    let footer = styles.get_ref(PageElem::footer);
182	    let (header, footer) = if matches!(number_align.y(), Some(OuterVAlignment::Top)) {
183	        (header.as_ref().unwrap_or(&numbering_marginal), footer.as_ref().unwrap_or(&None))
184	    } else {
185	        (header.as_ref().unwrap_or(&None), footer.as_ref().unwrap_or(&numbering_marginal))
186	    };
187	
188	    // Layout the children.
189	    let area = size - margin.sum_by_axis();
190	    let fragment = layout_flow(
191	        &mut engine,
192	        children,
193	        &mut locator,
194	        styles,
195	        Regions::repeat(area, area.map(Abs::is_finite)),
196	        ColumnOptions {
197	            count: styles.get(PageElem::columns),
198	            balanced: styles.get(ColumnsElem::balanced),
199	            gutter: styles.get(ColumnsElem::gutter).resolve(styles),
200	        },
201	        FlowMode::Root,
202	    )?;
203	
204	    // Layouts a single marginal.
205	    let mut layout_marginal = |content: &Option<Content>, area, align| {
206	        let Some(content) = content else { return Ok(None) };
207	        let aligned = content.clone().set(AlignElem::alignment, align);
208	        crate::layout_frame(
209	            &mut engine,
210	            &aligned,
211	            locator.next(&content.span()),
212	            styles,
213	            Region::new(area, Axes::splat(true)),
214	        )
215	        .map(Some)
216	    };
217	
218	    // Layout marginals.
219	    let mut layouted = Vec::with_capacity(fragment.len());
220	
221	    let header = header.clone().map(|h| h.artifact(ArtifactKind::Header));
222	    let footer = footer.clone().map(|f| f.artifact(ArtifactKind::Footer));
223	    let background = background.clone().map(|b| b.artifact(ArtifactKind::Background));
224	
225	    for inner in fragment {
226	        let header_size = Size::new(inner.width(), margin.top - header_ascent);
227	        let footer_size = Size::new(inner.width(), margin.bottom - footer_descent);
228	        let full_size = inner.size() + margin.sum_by_axis() + bleed.sum_by_axis();
229	        let mid = HAlignment::Center + VAlignment::Horizon;
230	        layouted.push(LayoutedPage {
231	            inner,
232	            fill: fill.clone(),
233	            numbering: numbering.clone(),
234	            supplement: supplement.clone(),
235	            header: layout_marginal(&header, header_size, Alignment::BOTTOM)?,
236	            footer: layout_marginal(&footer, footer_size, Alignment::TOP)?,
237	            background: layout_marginal(&background, full_size, mid)?,
238	            foreground: layout_marginal(foreground, full_size, mid)?,
239	            margin,
240	            margin_two_sided,
241	            bleed,
242	            bleed_two_sided,
243	            binding,
244	        });
245	    }
246	
247	    Ok(layouted)
248	}
